const REAL_IMAGE_BASE64 = {
  png: 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgYGD4DwABBAEAX+XDSwAAAABJRU5ErkJggg==',
  pngReplacement: 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4////fwAJ+wP9KobjigAAAABJRU5ErkJggg==',
  progressiveJpeg: '',
  adam7Png: 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAAHncGNIAAAADElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC',
  topDownBmp: 'Qk06AAAAAAAAADYAAAAoAAAAAQAAAP////8BABgAAAAAAAQAAADEDgAAxA4AAAAAAAAAAAAAAAD/AA==',
  jpeg: '',
  webp: 'UklGRhoAAABXRUJQVlA4TA4AAAAvAAAAAAcQEf0PRET/Aw==',
  bmp: 'Qk06AAAAAAAAADYAAAAoAAAAAQAAAAEAAAABABgAAAAAAAQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==',
};

const REAL_IMAGE_BYTES = Object.fromEntries(
  Object.entries(REAL_IMAGE_BASE64).map(([name, value]) => [name, Buffer.from(value, 'base64')]),
);

const FAKE_IMAGE_BYTES = {

  missingPltePng: Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAMAAAAoyzS7AAAACklEQVR4nGNgAAAAAgABSK+kcQAAAABJRU5ErkJggg==', 'base64'),
  invalidSofSosJpeg: Buffer.from('/9j/wAALCAABAAEBAREA/9oACAECAAA/AAD/2Q==', 'base64'),
  zeroVp8Webp: Buffer.from('UklGRhYAAABXRUJQVlA4IAoAAAAAAAAAAAAAAAAA', 'base64'),
  invalidBitfieldsBmp: Buffer.from('Qk06AAAAAAAAADYAAAAoAAAAAQAAAAEAAAABACAAAwAAAAQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==', 'base64'),
  png: (() => {
    const signature = Buffer.from('89504e470d0a1a0a', 'hex');
    const ihdr = Buffer.alloc(25);
    ihdr.writeUInt32BE(13, 0);
    ihdr.write('IHDR', 4, 'ascii');
    ihdr.writeUInt32BE(1, 8);
    ihdr.writeUInt32BE(1, 12);
    ihdr[16] = 8;
    ihdr[17] = 2;
    return Buffer.concat([signature, ihdr, Buffer.from('0000000049454e4400000000', 'hex')]);
  })(),
  jpeg: Buffer.from('ffd8ffe00002ffd9', 'hex'),
  webp: (() => {
    const buffer = Buffer.alloc(12);
    buffer.write('RIFF', 0, 'ascii');
    buffer.writeUInt32LE(4, 4);
    buffer.write('WEBP', 8, 'ascii');
    return buffer;
  })(),
  bmp: Buffer.from('Qk06AAAAAAAAADYAAAAoAAAAAQAAAAEAAAABACAAAwAAAAQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==', 'base64'),
};

function dataUrl(mime, bytes) {
  return `data:${mime};base64,${bytes.toString('base64')}`;
}

function createNativeImageMock() {
  const supported = [
    REAL_IMAGE_BYTES.png,
    REAL_IMAGE_BYTES.pngReplacement,
    REAL_IMAGE_BYTES.jpeg,
    REAL_IMAGE_BYTES.progressiveJpeg,
    REAL_IMAGE_BYTES.adam7Png,
  ];
  return {
    createFromBuffer(buffer) {
      const decodable = supported.some((fixture) => fixture.equals(buffer));
      return {
        isEmpty() { return !decodable; },
        getSize() { return decodable ? { width: 1, height: 1 } : { width: 0, height: 0 }; },
      };
    },
  };
}

module.exports = {
  REAL_IMAGE_BYTES,
  FAKE_IMAGE_BYTES,
  createNativeImageMock,
  dataUrl,
};
